    @Test fun nestedSchedulesAreDetachedAndPublicCollectionsStayFrozen() {
        val source = mutableListOf(com.greatwall.callring.contracts.settings.TimeWindow(1320, 120))
        val map = linkedMapOf(7 to source)
        val api = com.greatwall.callring.contracts.settings.WorkScheduleSettings("America/New_York", map, source, Long.MAX_VALUE, Long.MIN_VALUE)
        val domain = api.toDomain()
        source.clear(); map.clear()
        val projected = domain.toContract()
        assertEquals(listOf(com.greatwall.callring.contracts.settings.TimeWindow(1320, 120)), projected.weekly[7])
        assertEquals(projected.makeup, projected.weekly[7])
        assertEquals(Long.MAX_VALUE, projected.configVersion)
        assertEquals(Long.MIN_VALUE, projected.effectiveFromEpochMillis)
        try { (projected.weekly as MutableMap).clear(); fail("mutable map") } catch (_: UnsupportedOperationException) {}
        try { (projected.weekly.getValue(7) as MutableList).clear(); fail("mutable windows") } catch (_: UnsupportedOperationException) {}
        assertEquals(domain, projected.toDomain())
    }
    @Test fun originalAndCurrentFactsRetainAllMetadataAndPublicJsonShape() {
        val fact = com.greatwall.callring.domain.model.ClassificationFact(false, com.greatwall.callring.domain.model.WorkReason.UNKNOWN, null, false, "Pacific/Apia", 17, null, 29)
        assertEquals(fact, fact.toContract().toDomain())
        val json = safeValue(fact) as AiJson.Obj
        assertEquals(AiJson.Str("UNKNOWN"), json.fields["reason"])
        assertEquals(AiJson.Null, json.fields["calendarVersion"])
        assertEquals(safeValue(fact.toContract()), json)
    }
